"How to pray the Rosary": "Como rezar o Terço",
"On the crucifix, make the Sign of the Cross and pray the Apostles’ Creed.": "No crucifixo, faça o sinal da cruz e reze o Credo dos Apóstolos.",
"On the first large bead, pray the Our Father.": "Na primeira conta grande, reze o Pai-Nosso.",
"On the next three beads, pray a Hail Mary each for faith, hope, and charity, then the Glory Be.": "Nas três contas seguintes, reze uma Ave-Maria em cada uma pela fé, pela esperança e pela caridade, e depois o Glória.",
"Announce the first mystery, and pray the Our Father on the large bead.": "Anuncie o primeiro mistério e reze o Pai-Nosso na conta grande.",
"On the ten small beads, pray ten Hail Marys while meditating on the mystery.": "Nas dez contas pequenas, reze dez Ave-Marias meditando o mistério.",
"End the decade with the Glory Be and the Fatima Prayer. Repeat for the other four mysteries.": "Termine a dezena com o Glória e a oração de Fátima. Repita nos outros quatro mistérios.",
"At the centerpiece, finish with the Hail, Holy Queen and the closing prayer.": "Na medalha central, termine com a Salve-Rainha e a oração final.",
