"Choose a plan and read a little each day. Each reading links to the chapter on the USCCB website (New American Bible). Your progress is saved in this browser.": "Escolha um plano e leia um pouco cada dia. Cada leitura leva ao capítulo no site da USCCB (New American Bible, em inglês). O seu progresso fica guardado neste navegador.",
"The Four Gospels": "Os quatro Evangelhos",
"Walk with Jesus through Matthew, Mark, Luke, and John in a month.": "Caminhe com Jesus por Mateus, Marcos, Lucas e João em um mês.",
"Start this plan": "Começar este plano",
"Psalms and Proverbs": "Salmos e Provérbios",
"Pray the Psalms and learn wisdom from Proverbs, about three chapters a day.": "Reze os Salmos e aprenda sabedoria com os Provérbios, cerca de três capítulos por dia.",
"The New Testament": "O Novo Testamento",
"From Matthew to Revelation in three months.": "De Mateus ao Apocalipse em três meses.",
"The Whole Bible in a Year": "A Bíblia inteira em um ano",
"All 73 books of the Catholic Bible, about four chapters a day.": "Os 73 livros da Bíblia católica, cerca de quatro capítulos por dia.",
"The core teachings of the Catholic faith, each with the Scripture passages and Catechism paragraphs behind it, the witness of the Church Fathers, and charitable answers to the objections Catholics most often hear.": "Os ensinamentos centrais da fé católica, cada um com as passagens da Escritura e os parágrafos do Catecismo que o fundamentam, o testemunho dos Padres da Igreja e respostas caridosas às objeções que os católicos mais ouvem.",
