"Announcements from the Sanctify team will appear here soon.": "Em breve aparecerão aqui os anúncios da equipe do Sanctify.",
"to show them on a public profile and earn Community badges.": "para mostrá-las num perfil público e ganhar insígnias da Comunidade.",
"Prayer badges count the days you mark in your prayer tracker; finishing a Rosary, chaplet, or other guided prayer marks it for you.": "As insígnias de oração contam os dias que você marca no seu registro de oração; terminar um Rosário, um terço ou outra oração guiada marca-o automaticamente.",
