"Erase your saved entries, novenas, intentions, prayer record, badges, and settings from this device? This can’t be undone. You may want to download a backup first.": "Apagar deste dispositivo os itens guardados, novenas, intenções, registro de oração, insígnias e configurações? Não é possível desfazer. Talvez queira baixar um backup antes.",
"Replace what’s on this device with the backup from {*}?": "Substituir o que está neste dispositivo pelo backup de {*}?",
"follows the Roman Missal of 1962 and its calendar: the old feasts and seasons, Ember Days, the Latin Mass explained, and the fifteen mysteries of the Rosary. Its prayers are those of the Roman Catholic edition.": "segue o Missal Romano de 1962 e o seu calendário: as antigas festas e tempos, as Têmporas, a missa latina explicada e os quinze mistérios do Rosário. As suas orações são as da edição católica romana.",
