"A weekday in {*} — open the Calendar tab to see what’s coming up.": "Um dia de semana em {*}: abra o Calendário para ver o que vem aí.",
"Observances on this day are hidden by your filters.": "Os seus filtros ocultam as celebrações deste dia.",
"A season of hopeful preparation for the coming of Christ, both at Christmas and at the end of time.": "Um tempo de preparação esperançosa para a vinda de Cristo, no Natal e no fim dos tempos.",
"The Church celebrates the birth of Christ, from Christmas Day through the Baptism of the Lord.": "A Igreja celebra o nascimento de Cristo, do Natal ao Batismo do Senhor.",
"The “ordinal,” or counted, weeks of the year, when the Church reflects on the public life and teaching of Christ.": "As semanas “ordinais”, ou numeradas, do ano, quando a Igreja medita a vida pública e o ensinamento de Cristo.",
"Forty days of prayer, fasting, and almsgiving in preparation for Easter.": "Quarenta dias de oração, jejum e esmola em preparação para a Páscoa.",
"The three holiest days of the year: the Lord’s Supper, his Passion and death, and his Resurrection.": "Os três dias mais santos do ano: a Ceia do Senhor, a sua Paixão e morte, e a sua Ressurreição.",
"Fifty days of rejoicing in the Resurrection, from Easter Sunday to Pentecost.": "Cinquenta dias de alegria pela Ressurreição, do Domingo de Páscoa a Pentecostes.",
"Four weeks of preparation for the coming of Christ, at Christmas and at the end of time.": "Quatro semanas de preparação para a vinda de Cristo, no Natal e no fim dos tempos.",
"From the Nativity to the Commemoration of the Baptism of Our Lord on January 13.": "Da Natividade à Comemoração do Batismo de Nosso Senhor, a 13 de janeiro.",
"The Sundays after the Epiphany, when Christ is made known to the nations.": "Os domingos depois da Epifania, quando Cristo se dá a conhecer às nações.",
"The three weeks before Lent. The Gloria and the Alleluia fall silent, and violet is worn.": "As três semanas antes da Quaresma. Calam-se o Glória e o Aleluia, e usa-se o roxo.",
"Forty days of fasting, prayer, and almsgiving, from Ash Wednesday.": "Quarenta dias de jejum, oração e esmola, a partir da Quarta-feira de Cinzas.",
"The last two weeks of Lent, from Passion Sunday through Holy Week. Crosses and images are veiled.": "As duas últimas semanas da Quaresma, do Domingo da Paixão à Semana Santa. Cobrem-se as cruzes e as imagens.",
"From Easter Sunday to the Saturday after Pentecost.": "Do Domingo de Páscoa ao sábado depois de Pentecostes.",
"From Trinity Sunday until Advent: the long season of the Church’s growth.": "Do domingo da Trindade até o Advento: o longo tempo do crescimento da Igreja.",
"Forty days of fasting and joyful preparation for the Nativity of Christ, from November 15 to December 24.": "Quarenta dias de jejum e alegre preparação para a Natividade de Cristo, de 15 de novembro a 24 de dezembro.",
"The feasts of the birth of Christ and of his baptism in the Jordan, from December 25 to the leave-taking of Theophany.": "As festas do nascimento de Cristo e do seu batismo no Jordão, de 25 de dezembro ao encerramento da Teofania.",
"The weeks of the Triodion that prepare for Great Lent, from the Sunday of the Publican and the Pharisee to Forgiveness Sunday.": "As semanas do Triódion que preparam a Grande Quaresma, do domingo do Publicano e do Fariseu ao domingo do Perdão.",
"Forty days of fasting, prayer, and almsgiving, beginning on Clean Monday.": "Quarenta dias de jejum, oração e esmola, a partir da Segunda-feira Pura.",
"From Lazarus Saturday and the Entry into Jerusalem through the Passion of Christ to Great and Holy Saturday.": "Do Sábado de Lázaro e da Entrada em Jerusalém, passando pela Paixão de Cristo, ao Grande e Santo Sábado.",
"Christ is risen! Forty days of Paschal joy, followed by the Ascension and Pentecost.": "Cristo ressuscitou! Quarenta dias de alegria pascal, seguidos da Ascensão e de Pentecostes.",
"A fast from the Monday after All Saints Sunday until the feast of Sts. Peter and Paul on June 29.": "Um jejum desde a segunda-feira depois do domingo de Todos os Santos até a festa de são Pedro e são Paulo, a 29 de junho.",
"Two weeks of fasting in honor of the Theotokos, from August 1 to 14, before her Dormition.": "Duas semanas de jejum em honra da Theotokos, de 1 a 14 de agosto, antes da sua Dormição.",
"The Sundays after Pentecost, when the Church follows the public ministry of Christ.": "Os domingos depois de Pentecostes, quando a Igreja acompanha o ministério público de Cristo.",
