"Credits": "Créditos",
"The Sanctify team": "A equipe do Sanctify",
"Sanctify is made and looked after by a small team, and kept friendly by its moderators.": "O Sanctify é feito e cuidado por uma pequena equipe, e seus moderadores o mantêm acolhedor.",
"Administrator": "Administrador",
"The Community": "A Comunidade",
"Thank you to everyone who posts, prays for others, and writes in the Community Wiki. Many of the changes in Sanctify 0.9 began as members’ suggestions in the forum.": "Obrigado a todos que publicam, rezam pelos outros e escrevem na wiki da comunidade. Muitas das mudanças do Sanctify 0.9 começaram como sugestões de membros no fórum.",
"Scripture and the Catechism": "A Escritura e o Catecismo",
"The Bible on the site is the Douay-Rheims, with Bishop Challoner’s notes, which is in the public domain. The Catechism of the Catholic Church is © Libreria Editrice Vaticana.": "A Bíblia do site é a Douay-Rheims, com as notas do bispo Challoner, que está em domínio público. O Catecismo da Igreja Católica é © Libreria Editrice Vaticana.",
"Images and recordings": "Imagens e gravações",
"Pictures of the saints, icons, and books, and the hymn recordings, come from Wikipedia and Wikimedia Commons. Each one is credited on the site with its author and license.": "As imagens de santos, ícones e livros, e as gravações de hinos, vêm da Wikipédia e do Wikimedia Commons. Cada uma é creditada no site com seu autor e licença.",
"Languages": "Idiomas",
"Sanctify is translated by hand into Spanish, Polish, French, Portuguese, Italian, German, Russian, and Ukrainian, with the common prayers in the words Catholics pray in each language.": "O Sanctify é traduzido à mão para espanhol, polonês, francês, português, italiano, alemão, russo e ucraniano, com as orações comuns nas palavras que os católicos rezam em cada língua.",
"Type": "Tipografia",
