"members can report a post or reply. Review them here, then remove it or dismiss the report.": "os membros podem denunciar uma publicação ou resposta. Reveja-as aqui e depois remova-a ou descarte a denúncia.",
"Accounts:": "Contas:",
"see every account with its posts and replies, ban a member for a day, a week, a month, or for good, and remove everything they have posted.": "ver cada conta com suas publicações e respostas, banir um membro por um dia, uma semana, um mês ou para sempre, e remover tudo o que ele publicou.",
"Members:": "Membros:",
"mute a member so they can read and pray but not post, send them a private warning, and keep private notes on their account.": "silenciar um membro para que ele possa ler e rezar, mas não publicar, enviar-lhe uma advertência privada e manter notas privadas sobre a conta.",
"Threads:": "Tópicos:",
"open any Community post to remove it, pin it to the top, lock it so it takes no new replies, or move it to another category.": "abrir qualquer publicação da Comunidade para removê-la, fixá-la no topo, bloqueá-la para novas respostas ou movê-la para outra categoria.",
"Settings:": "Configurações:",
"make the whole Community read-only for a while, and keep a list of blocked words that can’t be posted.": "deixar toda a Comunidade só para leitura por um tempo e manter uma lista de palavras bloqueadas que não podem ser publicadas.",
