"Weeping on a rock in a Lithuanian field, the Child in her arms": "Chorando sobre uma rocha num campo lituano, com o Menino nos braços",
"Šiluva at Dusk": "Šiluva ao anoitecer",
"Amber light over the fields of Lithuania": "Luz âmbar sobre os campos da Lituânia",
"La Vang": "La Vang",
"Comfort for the persecuted, beneath a banyan tree": "Consolo para os perseguidos, sob uma figueira-de-bengala",
